CREATE TABLE users (id BIGSERIAL PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(80) NOT NULL,bio VARCHAR(500),role VARCHAR(20) NOT NULL DEFAULT 'USER' CHECK (role IN ('USER','ADMIN')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,slug VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(500),color VARCHAR(20) NOT NULL);
CREATE TABLE discussions (id BIGSERIAL PRIMARY KEY,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','PLANNED','DONE','CLOSED')),author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id BIGINT NOT NULL REFERENCES categories(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY,body TEXT NOT NULL,author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,discussion_id BIGINT NOT NULL REFERENCES discussions(id) ON DELETE CASCADE,parent_id BIGINT REFERENCES comments(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE votes (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,discussion_id BIGINT NOT NULL REFERENCES discussions(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT uk_vote_user_discussion UNIQUE(user_id,discussion_id));
CREATE INDEX idx_discussions_activity ON discussions(updated_at DESC);CREATE INDEX idx_discussions_created ON discussions(created_at DESC);CREATE INDEX idx_discussions_category ON discussions(category_id);CREATE INDEX idx_discussions_search ON discussions USING gin(to_tsvector('simple',title||' '||body));CREATE INDEX idx_comments_discussion ON comments(discussion_id,created_at);CREATE INDEX idx_comments_parent ON comments(parent_id);CREATE INDEX idx_votes_discussion ON votes(discussion_id);
